package com.today.app.ui.components

import android.content.Context
import com.today.app.data.PetSpecies
import org.json.JSONArray
import org.json.JSONObject

// Generated by tools/character_art/pets.py into assets/pet_art.json. Edit the art there, not by hand.

/** The pet art box (art units); the pet stands on its bottom edge. */
internal const val PET_W = 240f
internal const val PET_H = 200f

/** Two animation frames (idle and tail wag / wing flap / nibble...) and the egg it hatches from. */
internal class PetDrawing(val frames: List<List<ArtLayer>>, val egg: List<ArtLayer>)

internal object PetArt {
    @Volatile
    private var pets: Map<PetSpecies, PetDrawing>? = null

    fun get(context: Context): Map<PetSpecies, PetDrawing> = pets ?: synchronized(this) { pets ?: load(context).also { pets = it } }

    private fun load(context: Context): Map<PetSpecies, PetDrawing> {
        val text = context.assets.open("pet_art.json").use { it.readBytes().decodeToString() }
        val root = JSONObject(text).getJSONObject("pets")
        val shapes = HashMap<String, PathShape>()
        fun layers(arr: JSONArray) = List(arr.length()) { i ->
            val l = arr.getJSONArray(i)
            ArtLayer(
                shape = shapes.getOrPut(l.getString(0)) { PathShape.parse(l.getString(0)) },
                fill = Paint.parse(l.getString(1)),
                stroke = Paint.parse(l.getString(2)),
                width = l.getDouble(3).toFloat(),
                alpha = l.getDouble(4).toFloat(),
                clipShape = l.getString(5).takeIf { it.isNotEmpty() }?.let { d -> shapes.getOrPut(d) { PathShape.parse(d) } },
            )
        }
        return PetSpecies.entries.associateWith { sp ->
            val p = root.getJSONObject(sp.name)
            val frames = p.getJSONArray("frames")
            PetDrawing(List(frames.length()) { layers(frames.getJSONArray(it)) }, layers(p.getJSONArray("egg")))
        }
    }
}
